import pytest

from src.api.routes.items import (
    favorite_item,
    get_item,
    list_favorite_items,
    list_items,
    unfavorite_item,
)
from src.api.routes.users import get_user


@pytest.fixture(autouse=True)
def _reset_favorites():
    yield
    for user in (get_user(1), get_user(2)):
        if user is not None:
            user.favorite_item_ids.clear()


def test_list_items_omits_archived_items_by_default():
    items = list_items()
    assert all(not item["archived"] for item in items)


def test_get_item_returns_matching_item():
    assert get_item(1)["name"] == "Notebook"


def test_favorite_item_records_favorite():
    favorite_item(1, 1)
    assert [item["id"] for item in list_favorite_items(1)] == [1]


def test_favorite_item_is_idempotent():
    favorite_item(1, 1)
    favorite_item(1, 1)
    assert [item["id"] for item in list_favorite_items(1)] == [1]


def test_favorite_non_owned_item_fails():
    with pytest.raises(PermissionError):
        favorite_item(1, 3)
    assert list_favorite_items(1) == []


def test_unfavorite_removes_favorite():
    favorite_item(1, 1)
    unfavorite_item(1, 1)
    assert list_favorite_items(1) == []


def test_unfavorite_is_idempotent_when_not_favorited():
    unfavorite_item(1, 1)
    unfavorite_item(1, 1)
    assert list_favorite_items(1) == []


def test_list_favorites_returns_only_user_favorites():
    favorite_item(1, 2)
    favorite_item(2, 3)
    assert [item["id"] for item in list_favorite_items(1)] == [2]
    assert [item["id"] for item in list_favorite_items(2)] == [3]


def test_favorite_unknown_item_raises():
    with pytest.raises(ValueError):
        favorite_item(1, 999)


def test_favorite_unknown_user_raises():
    with pytest.raises(ValueError):
        favorite_item(999, 1)

